{
  "title": "Đà Lạt một góc, trọn một ngày",
  "summary": "Một ngày thong thả quanh khu trung tâm, từ gà trống trên tháp chuông đến mì Quảng chiều và cà phê đêm, không cần rời xa quá vài con phố.",
  "stops": [
    {
      "poi_id": "p3",
      "kind": "activity",
      "must_do_id": "p3",
      "note": "Giữ nguyên điểm khởi đầu, sáng muộn vẫn kịp ngắm gà trống và mái ngói đỏ không cần đi xa.",
      "must_do_id": "p3"
    },
    {
      "poi_id": "p11",
      "kind": "activity",
      "must_do_id": "p11",
      "note": "Dinh Bảo Đại III ở ngay cạnh, vừa đủ một vòng chậm rãi để nghe chuyện xưa mà chân không mỏi.",
      "must_do_id": "p11"
    },
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bữa trưa ngồi lại cho đàng hoàng, nem nướng thơm lừng ngay khu này, khỏi cần xe cộ lòng vòng.",
      "must_do_id": null
    },
    {
      "poi_id": "p286",
      "kind": "activity",
      "must_do_id": null,
      "note": "Công viên hoa gần đó, đi bộ tản mạn buổi chiều nhẹ tênh, đúng kiểu dễ chịu không vội.",
      "must_do_id": null
    },
    {
      "poi_id": "p179",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bánh căn nóng hổi cho bữa tối, vẫn loanh quanh khu trung tâm, ngon quá (so tasty) mà không tốn sức.",
      "must_do_id": null
    },
    {
      "poi_id": "p49",
      "kind": "activity",
      "must_do_id": null,
      "note": "Kết ngày bằng cà phê đêm ở Mây Lang Thang, ngồi một chỗ ngắm phố núi lên đèn.",
      "must_do_id": null
    }
  ]
}
```

```json
{
  "title": "Đà Lạt chậm rãi, trọn một góc phố",
  "summary": "Một ngày quẩn quanh khu trung tâm, đi bộ nhẹ tênh, ăn ngon và ngắm phố núi về đêm.",
  "stops": [
    {
      "poi_id": "p3",
      "kind": "activity",
      "must_do_id": "p3",
      "note": "Giữ nguyên điểm hẹn sáng nay, ghé sớm cho vắng và mát, ngắm gà trống trên nóc là vui rồi."
    },
    {
      "poi_id": "p11",
      "kind": "activity",
      "must_do_id": "p11",
      "note": "Ngay cạnh nhà thờ, khỏi cần xe cộ gì nhiều, vào xem dinh thự cũ cho trọn buổi sáng."
    },
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": null,
      "note": "Trưa nay đổi gió, nem nướng ngồi ăn cho đàng hoàng, cảm ơn (thank you) cái bụng đã chờ."
    },
    {
      "poi_id": "p14",
      "kind": "activity",
      "must_do_id": null,
      "note": "Quảng trường gần đây thôi, tản bộ chút cho tiêu cơm, đứng ngắm công trình lạ mắt giữa phố."
    },
    {
      "poi_id": "p22",
      "kind": "meal",
      "must_do_id": null,
      "note": "Tối ngồi xuống quán Hà Thành, ăn chậm, kể chuyện linh tinh, khỏi lo chạy đâu xa."
    },
    {
      "poi_id": "p49",
      "kind": "activity",
      "must_do_id": null,
      "note": "Đêm xuống thì ghé Mây Lang Thang, cà phê ấm, ngắm phố núi lên đèn, thong thả rồi về."
    }
  ]
}
```
